"use client"; import { useParams } from "next/navigation"; import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"; import { api } from "@/lib/api/services"; import { LoadingState, EmptyState, ErrorState } from "@/components/PageStates"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Textarea } from "@/components/ui/textarea"; import { Label } from "@/components/ui/label"; import { Badge } from "@/components/ui/badge"; import { useState, useRef } from "react";
export default function WorkspaceDetail(){const {id}=useParams<{id:string}>();const qc=useQueryClient();const ws=useQuery({queryKey:["workspace",id],queryFn:()=>api.workspace(id)});const docs=useQuery({queryKey:["ws-docs",id],queryFn:()=>api.wsDocuments(id)});const convs=useQuery({queryKey:["convs",id],queryFn:()=>api.conversations(id)});
 const [question,setQuestion]=useState("");const [answer,setAnswer]=useState("");const [citations,setCitations]=useState<{page_number?:number;source_label?:string}[]>([]);const [toolOut,setToolOut]=useState("");const fileRef=useRef<HTMLInputElement>(null);
 const upload=useMutation({mutationFn:(f:File)=>api.uploadDocument(id,f),onSuccess:()=>qc.invalidateQueries({queryKey:["ws-docs",id]})});
 const indexM=useMutation({mutationFn:(did:string)=>api.docIndex(id,did),onSuccess:()=>qc.invalidateQueries({queryKey:["ws-docs",id]})});
 const chatM=useMutation({mutationFn:()=>api.chat(id,{question}),onSuccess:(d)=>{setAnswer((d.answer||d.response||"") as string);setCitations((d.citations||[]) as {page_number?:number;source_label?:string}[]);qc.invalidateQueries({queryKey:["convs",id]});}});
 const toolM=useMutation({mutationFn:(tool:string)=>api.research(id,tool,{question:question||"Summarize the key findings"}),onSuccess:(d)=>setToolOut(JSON.stringify(d,null,2))});
 const delConv=useMutation({mutationFn:(cid:string)=>api.deleteConversation(id,cid),onSuccess:()=>qc.invalidateQueries({queryKey:["convs",id]})});
 if(ws.isLoading||docs.isLoading) return <LoadingState/>; if(ws.error) return <ErrorState message="Workspace not found or access denied" />;
 return <div><p className="text-xs text-zinc-500"><a href="/app/workspaces" className="hover:underline">Workspaces</a> / {ws.data?.name}</p><h1 className="mt-2 text-2xl font-semibold tracking-tight">{ws.data?.name}</h1>{ws.data?.description&&<p className="mt-1 text-sm text-zinc-400">{ws.data.description}</p>}
 <div className="mt-8 grid gap-8 lg:grid-cols-2"><section><h2 className="text-base font-semibold">Documents</h2>
 <input ref={fileRef} type="file" accept=".pdf,.docx,.txt" className="hidden" onChange={e=>{const f=e.target.files?.[0];if(f)upload.mutate(f);}}/><Button className="mt-3" size="sm" onClick={()=>fileRef.current?.click()} disabled={upload.isPending}>{upload.isPending?"Uploading…":"Upload PDF / DOCX / TXT"}</Button>
 {upload.error&&<p className="mt-2 text-sm text-red-300">Upload failed. Check file type and size.</p>}
 <div className="mt-4">{!docs.data?.length?<EmptyState title="No documents yet" desc="Upload a paper, then index it for cited answers."/>:<ul className="divide-y divide-white/[0.06] rounded-lg border border-white/[0.08] bg-[#0F1511]">{docs.data.map(d=><li key={d.id} className="flex items-center justify-between gap-3 px-4 py-3"><div className="min-w-0"><p className="truncate text-sm font-medium">{d.original_filename||d.filename}</p><p className="text-xs text-zinc-500">{d.file_type} · {d.status}</p></div><Button size="sm" variant="outline" onClick={()=>indexM.mutate(d.id)} disabled={indexM.isPending}>Index</Button></li>)}</ul>}</div>
 <h2 className="mt-8 text-base font-semibold">Conversations</h2>{!convs.data?.length?<p className="mt-2 text-sm text-zinc-500">No conversations yet.</p>:<ul className="mt-3 space-y-2">{convs.data.map(c=><li key={c.id} className="flex items-center justify-between rounded-md border border-white/[0.08] px-3 py-2 text-sm"><span>{c.title||"Untitled"}</span><Button size="sm" variant="ghost" onClick={()=>{if(confirm("Delete this conversation?"))delConv.mutate(c.id);}}>Delete</Button></li>)}</ul>}</section>
 <section><h2 className="text-base font-semibold">Research studio</h2><div className="mt-3 space-y-3"><Label htmlFor="q">Ask your documents</Label><Textarea id="q" rows={4} value={question} onChange={e=>setQuestion(e.target.value)} placeholder="What does the literature say about…?"/><div className="flex flex-wrap gap-2"><Button onClick={()=>chatM.mutate()} disabled={!question||chatM.isPending}>{chatM.isPending?"Thinking…":"Ask with citations"}</Button>{["summary","key-points","questions","flashcards"].map(t=><Button key={t} variant="outline" size="sm" onClick={()=>toolM.mutate(t)} disabled={toolM.isPending}>{t}</Button>)}</div>
 {chatM.error&&<p className="text-sm text-red-300">Chat failed. Index documents first, then retry.</p>}
 {answer&&<div className="rounded-lg border border-white/[0.08] bg-[#0F1511] p-4"><p className="text-sm leading-relaxed whitespace-pre-wrap">{answer}</p>{citations.length>0&&<div className="mt-4 border-t border-white/[0.06] pt-3"><p className="text-xs font-medium text-zinc-400">Sources</p><ul className="mt-2 space-y-1">{citations.map((c,i)=><li key={i} className="text-xs text-zinc-400">[{i+1}] {c.source_label||"Document"}{c.page_number?` · Page ${c.page_number}`:""}</li>)}</ul></div>}</div>}
 {toolOut&&<pre className="max-h-80 overflow-auto rounded-lg border border-white/[0.08] bg-zinc-900 p-4 text-xs whitespace-pre-wrap">{toolOut}</pre>}</div></section></div></div>;}
